"""Actual native local-step cancellation with real descendant attachment jobs."""
import argparse,json,pathlib,subprocess,tempfile
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();rows=[]
common="import{defineNativeSuite}from "+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';import{setTimeout as wait}from'node:timers/promises';"
def run(name,body,code=0):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+body);process=subprocess.run([str(a.executable),'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html')],capture_output=True,timeout=15);(root/'stdout.bin').write_bytes(process.stdout);(root/'stderr.bin').write_bytes(process.stderr);assert process.returncode==code and not process.stderr,(name,process.returncode,process.stdout,process.stderr)
 v=json.loads((root/'actual.json').read_text());assert all(s['receipt']!='pending'for s in v['steps']);assert all(s['receiptMonotonicMs']>=s.get('callbackReceiptMonotonicMs',s['startedMonotonicMs'])for s in v['steps']);rows.append({'scope':name,'actualExitCode':process.returncode,'report':str(root/'actual.json')});return v
v=run('body-local-skip-keeps-test-passed-and-real-file-absent',"export default defineNativeSuite({tests:[{title:'actual local skip',run:(_,i)=>i.step('source',s=>{void s.attach('canceled',{body:'actual bytes'});s.skip('actual local reason\\ud800')})}]});");assert v['attempts'][0]['status']=='passed'and v['attempts'][0]['expectedStatus']=='passed'and v['attempts'][0]['annotations']==[]and v['steps'][0]['status']=='skipped'and v['steps'][0]['stepSkip']['reason']=='actual local reason\ud800'and v['steps'][0]['receiptStepSkipRequestId']==v['steps'][0]['stepSkip']['requestId']and not v['attachments']and not v['globalErrors']
v=run('descendant-cause-raw-cleanup-fences-before-afterEach',"let childStarted=false,childRaw=false,sourceRaw=false;export default defineNativeSuite({hooks:{afterEach:[{run:()=>{assert(childRaw);assert(sourceRaw)}}]},tests:[{title:'actual nested scope',run:(_,i)=>i.step('source',async s=>{const child=i.step('child',async c=>{childStarted=true;try{await c.attach('canceled child',{body:'actual child'})}finally{childRaw=true}});while(!childStarted)await wait(1);try{s.skip('actual subtree')}finally{await child;sourceRaw=true}})}]});");assert v['attempts'][0]['status']=='passed'and len(v['steps'])==2 and all(s['status']=='skipped'for s in v['steps'])and all(s['stepSkip']['sourceStepId']==v['steps'][0]['id']for s in v['steps'])and not v['attachments']and not v['globalErrors']
v=run('child-local-skip-preserves-parent-and-outer-file-ownership',"export default defineNativeSuite({tests:[{title:'actual independent owner files',run:async(_,i)=>{await i.attach('outer',{body:'actual outer'});await i.step('parent',async p=>{const own=p.attach('parent',{body:'actual parent'});await i.step('child',c=>{void c.attach('canceled child',{body:'actual child'});c.skip('child only')});await own})}}]});");assert[s['status']for s in v['steps']]==['passed','skipped']and len(v['attachments'])==2 and {f['name']for f in v['attachments']}=={'outer','parent'}and pathlib.Path(next(f for f in v['attachments']if f['name']=='parent')['path']).read_bytes()==b'actual parent'and not v['globalErrors']
v=run('independent-sibling-local-causes-do-not-cross-cancel',"export default defineNativeSuite({tests:[{title:'two actual sources',run:async(_,i)=>{await i.step('first',s=>{void s.attach('first',{body:'actual'});s.skip('first cause')});await i.step('second',s=>{void s.attach('second',{body:'actual'});s.skip('second cause')});await i.step('unaffected',async s=>{await s.attach('retained',{body:'actual retained'})})}}]});");assert[s['status']for s in v['steps']]==['skipped','skipped','passed']and v['steps'][0]['stepSkip']['requestId']!=v['steps'][1]['stepSkip']['requestId']and len(v['attachments'])==1 and v['attachments'][0]['name']=='retained'and not v['globalErrors']
v=run('beforeEach-local-skip-does-not-skip-body-and-retains-real-cleanup',"let raw=false,ran=false;export default defineNativeSuite({hooks:{beforeEach:[{run:(_,i)=>i.step('hook local',async s=>{const file=s.attach('canceled',{body:'actual'});try{s.skip('hook step only')}finally{await assert.rejects(file);raw=true}})}],afterEach:[{run:()=>{assert(raw);assert(ran)}}]},tests:[{title:'actual body runs',run:()=>{ran=true}}]});");assert v['attempts'][0]['status']=='passed'and v['steps'][0]['callbackKind']=='beforeEach'and v['steps'][0]['status']=='skipped'and not v['attachments']and not v['globalErrors']
v=run('beforeAll-afterAll-local-step-files-have-independent-real-scopes',"const hook=title=>({run:(_,i)=>i.step(title,s=>{void s.attach(title,{body:'actual hook bytes'});s.skip(title+' local')})});export default defineNativeSuite({hooks:{beforeAll:[hook('beforeAll')],afterAll:[hook('afterAll')]},tests:[{title:'actual all hooks do not skip test',run:()=>{}}]});");assert v['attempts'][0]['status']=='passed'and {s['callbackKind']for s in v['steps']}=={'beforeAll','afterAll'}and all(s['status']=='skipped'for s in v['steps'])and not v['attachments']and not v['globalErrors']
v=run('false-local-modifier-preserves-real-file-commit',"export default defineNativeSuite({tests:[{title:'actual false control',run:(_,i)=>i.step('source',async s=>{const file=s.attach('committed',{body:'actual commit'});s.skip(false,'must not cancel');await file})}]});");assert v['steps'][0]['status']=='passed'and'stepSkip'not in v['steps'][0]and len(v['attachments'])==1 and pathlib.Path(v['attachments'][0]['path']).read_bytes()==b'actual commit'and not v['globalErrors']
v=run('genuine-raw-cleanup-error-cannot-be-excused-by-skip-or-expectation',"export default defineNativeSuite({tests:[{title:'actual raw cleanup error',expectedFailure:true,run:(_,i)=>i.step('source',async s=>{const file=s.attach('canceled',{body:'actual'});try{s.skip('accepted local cause')}finally{await assert.rejects(file);throw Error('actual raw cleanup failure')}})}]});",1);assert v['attempts'][0]['status']=='failed'and not v['attempts'][0]['expected']and 'actual raw cleanup failure'in v['attempts'][0]['error']and v['steps'][0]['status']=='skipped'and not v['steps'][0]['receiptOK']and 'actual raw cleanup failure'in v['steps'][0]['receiptError']and not v['attachments']
v=run('actual-own-timeout-retains-priority-over-late-local-request',"export default defineNativeSuite({tests:[{title:'actual prior deadline',run:async(_,i)=>{await assert.rejects(i.step('source',async s=>{void s.attach('canceled',{body:'actual'}).catch(()=>{});await wait(150);s.skip('late cause')},{timeout:80}),/Step timeout of 80ms exceeded/)}}]});");assert v['attempts'][0]['status']=='passed'and v['steps'][0]['status']=='timedOut'and'stepSkip'not in v['steps'][0]and not v['globalErrors']
v=run('real-retry-keeps-accepted-cause-and-artifact-owners-separate',"export default defineNativeSuite({tests:[{title:'actual retry',retries:1,run:async(_,i)=>{await i.step('local '+i.retry,s=>{void s.attach('canceled '+i.retry,{body:'actual'});s.skip('attempt '+i.retry)});await i.attach('retained '+i.retry,{body:'actual attempt '+i.retry});if(!i.retry)throw Error('actual first failure')}}]});");assert len(v['attempts'])==2 and v['summary']['flaky']==1 and len(v['attachments'])==2 and len({f['generation']for f in v['attachments']})==2 and len({s['stepSkip']['sourceStepId']for s in v['steps']})==2 and not v['globalErrors']
(receipt/'report.json').write_text(json.dumps({'passed':len(rows),'scope':'Actual native local-step.skip with pending step-owned files: native accepted cause and descendant cancellation, independent owners, real raw/file/cleanup fences and timeout/error/retry priority. No test.skip or declared skip conversion.','groups':rows},indent=2)+'\n');print('PASS',len(rows),'actual native local-step attachment process groups')
